 * TASK-21 livery smoke test.
 *
 * Verifies the end-to-end persistence + broadcast flow for ship
 * livery customization:
 *
 *   1. Claim a callsign (mint starter ship + session token).
 *   2. POST /api/ships/livery with a valid hex triple.
 *   3. GET /api/ships to confirm the colours stuck.
 *
 * The dev server must already be running (`npm run dev`) before this
 * test executes; playwright.config.ts's `webServer` block handles that.
 */
import { test, expect } from "@playwright/test";

const NEW_LIVERY = {
  primary: "#ff8800",
  secondary: "#222244",
  accent: "#ffff00",
};

test("livery endpoint persists paint colors end-to-end", async ({ request, page }) => {
  const consoleErrors: string[] = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") {
      consoleErrors.push(msg.text());
    }
  });

